from collections import deque

def transform(grid):
    R,C=len(grid),len(grid[0])
    # Find contiguous barrier-colored line of 2s and direction toward it.
    cells2=[(r,c) for r in range(R) for c in range(C) if grid[r][c]==2]
    if all(r==0 for r,c in cells2): dr,dc=1,0  # into board down
    elif all(r==R-1 for r,c in cells2): dr,dc=-1,0
    elif all(c==0 for r,c in cells2): dr,dc=0,1
    elif all(c==C-1 for r,c in cells2): dr,dc=0,-1
    else: raise ValueError('barrier not on edge')
    seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c] in (0,2) or (r,c) in seen: continue
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          x,y=q.pop(); comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            z=(x+dx,y+dy)
            if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z[0]][z[1]]==color:
              seen.add(z); q.append(z)
        comps.append((color,comp))
    # process components closest to the barrier first
    if dr==1: comps.sort(key=lambda x:max(r for r,c in x[1]),reverse=True)
    elif dr==-1: comps.sort(key=lambda x:min(r for r,c in x[1]))
    elif dc==1: comps.sort(key=lambda x:max(c for r,c in x[1]),reverse=True)
    else: comps.sort(key=lambda x:min(c for r,c in x[1]))
    out=[row[:] for row in grid]
    for color,comp in comps:
      for r,c in comp: out[r][c]=0
      loc=comp[:]
      while True:
        nxt=[(r+dr,c+dc) for r,c in loc]
        if any(r<0 or r>=R or c<0 or c>=C or out[r][c]!=0 for r,c in nxt): break
        loc=nxt
      for r,c in loc: out[r][c]=color
    return out

