src='''from collections import deque

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    barrier = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]
    if all(r == 0 for r, c in barrier):
        dr, dc = -1, 0
    elif all(r == rows - 1 for r, c in barrier):
        dr, dc = 1, 0
    elif all(c == 0 for r, c in barrier):
        dr, dc = 0, -1
    elif all(c == cols - 1 for r, c in barrier):
        dr, dc = 0, 1
    else:
        raise ValueError("The 2s must form a border line")

    seen = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            component = []
            while cells:
                x, y = cells.pop()
                component.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    point = (x + dx, y + dy)
                    if (0 <= point[0] < rows and 0 <= point[1] < cols
                            and point not in seen and grid[point[0]][point[1]] == color):
                        seen.add(point)
                        cells.append(point)
            components.append((color, component))

    if dr == 1:
        components.sort(key=lambda item: max(r for r, c in item[1]), reverse=True)
    elif dr == -1:
        components.sort(key=lambda item: min(r for r, c in item[1]))
    elif dc == 1:
        components.sort(key=lambda item: max(c for r, c in item[1]), reverse=True)
    else:
        components.sort(key=lambda item: min(c for r, c in item[1]))

    output = [row[:] for row in grid]
    for color, component in components:
        for r, c in component:
            output[r][c] = 0
        location = component[:]
        while True:
            next_location = [(r + dr, c + dc) for r, c in location]
            if any(r < 0 or r >= rows or c < 0 or c >= cols or output[r][c] != 0
                   for r, c in next_location):
                break
            location = next_location
        for r, c in location:
            output[r][c] = color
    return output
'''
